<script setup>
import {ref,computed,watch,nextTick,onMounted,onUnmounted} from 'vue';
import {Head,Link,router,usePage} from '@inertiajs/vue3';import axios from 'axios';import {modes,message} from '../art';
import Feedback from '../Components/Feedback.vue';import StudySheet from '../Components/StudySheet.vue';import StudyDock from '../Components/StudyDock.vue';
import StudyStatus from '../Components/StudyStatus.vue';import SlidingPanel from '../Components/SlidingPanel.vue';import {useStudyDelivery} from '../useStudyDelivery';import {answerKey} from '../studyDelivery';import {initialQuestionIndex,attemptAction} from '../attemptNavigation.mjs';
const props=defineProps({attempt:Object,bookmarks:Array}),page=usePage(),data=ref(props.attempt),clock=ref(Date.now()),offset=ref(new Date(props.attempt.server_now).getTime()-Date.now());
const positionKey='sushi:position:'+page.props.user.id+':'+data.value.id;
let savedItem=null;try{savedItem=sessionStorage.getItem(positionKey)}catch{}
const index=ref(initialQuestionIndex(data.value,savedItem)),finishing=ref(false),finishError=ref(''),reviewing=ref(false),navigator=ref(null),help=ref(null),menu=ref(null),heading=ref(null),submitDialog=ref(null),cardStage=ref(null);
watch(()=>props.attempt,attempt=>{const item=data.value.items[index.value]?.item_id;data.value=attempt;const at=attempt.items.findIndex(i=>i.item_id===item);index.value=at>=0?at:initialQuestionIndex(attempt);clock.value=Date.now();offset.value=new Date(attempt.server_now).getTime()-clock.value});
const q=computed(()=>data.value.items[index.value]),ended=computed(()=>data.value.status!=='active'),missing=computed(()=>data.value.items.filter(i=>!i.answer).length),action=computed(()=>attemptAction(data.value,index.value));
const remaining=computed(()=>data.value.deadline?Math.max(0,Math.ceil((new Date(data.value.deadline).getTime()-clock.value-offset.value)/1000)):null);
const timer=computed(()=>remaining.value===null?'':Math.floor(remaining.value/60)+':'+String(remaining.value%60).padStart(2,'0'));
function accept(r){data.value=r.data.attempt;page.props.achievement=r.data.achievement;page.props.community=r.data.community;const at=data.value.items.findIndex(i=>i.item_id===pending.value?.payload.item_id);if(at>=0)index.value=at}
const {pending,busy,error,status,send,retry,discard}=useStudyDelivery('sushi:pending:'+page.props.user.id+':attempt:'+data.value.id,'/attempts/'+data.value.id,accept);
const locked=computed(()=>busy.value||!!pending.value||finishing.value),canCheck=computed(()=>!ended.value&&!q.value?.checked&&['fresh','tutor'].includes(data.value.mode));
let interval,heartbeat,lastAction=Date.now();
function touch(){lastAction=Date.now()}
watch(()=>q.value?.checked,async checked=>{if(checked){await nextTick();cardStage.value?.reveal('.feedback')}});
async function move(i){index.value=i;navigator.value?.close();try{sessionStorage.setItem(positionKey,q.value.item_id)}catch{}await nextTick()}
function save(answer,check=false){if(ended.value||locked.value||q.value.checked)return;return send('answer',{item_id:q.value.item_id,answer,check,revision:data.value.revision,request_token:crypto.randomUUID()})}
function reload(){discard();router.reload()}
function requestFinish(){if(locked.value)return;if(data.value.mode==='fresh'){if(missing.value)return move(data.value.items.findIndex(i=>!i.answer));finish()}else submitDialog.value.open()}
async function finish(expired=false){
 if(finishing.value||busy.value||(!expired&&pending.value))return;
 finishing.value=true;finishError.value='';
 try{const response=await axios.post('/attempts/'+data.value.id+'/finish',{}, {timeout:20000});accept(response);if(ended.value){if(pending.value)discard();reviewing.value=false;finishing.value=false;await nextTick();submitDialog.value?.close();try{sessionStorage.removeItem(positionKey)}catch{}}}
 catch(e){finishError.value=message(e)}finally{finishing.value=false}
}
function advance(){if(locked.value)return;if(action.value.kind==='next')move(index.value+1);else if(action.value.kind==='missing')move(data.value.items.findIndex(i=>!i.answer));else if(action.value.kind==='finish')requestFinish();else if(index.value===data.value.items.length-1)reviewing.value=false;else move(index.value+1)}
function keys(e){const key=answerKey(e);if(key&&key<=4&&!locked.value&&!ended.value&&!q.value?.checked&&!document.querySelector('dialog[open]')){e.preventDefault();save(String.fromCharCode(64+key))}}
onMounted(()=>{window.addEventListener('pointerdown',touch);window.addEventListener('keydown',touch);window.addEventListener('keydown',keys);interval=setInterval(()=>{clock.value=Date.now();if(remaining.value===0&&!ended.value&&!busy.value&&!finishError.value)finish(true)},1000);heartbeat=setInterval(()=>{if(!document.hidden&&!ended.value)axios.post('/attempts/'+data.value.id+'/heartbeat',{active:Date.now()-lastAction<60000}).catch(()=>{})},15000)});
onUnmounted(()=>{clearInterval(interval);clearInterval(heartbeat);window.removeEventListener('pointerdown',touch);window.removeEventListener('keydown',touch);window.removeEventListener('keydown',keys)});
</script>
<template><Head :title="modes[data.mode]"/>
<div class="study-heading"><div><h1>{{modes[data.mode]}}</h1><p v-if="!ended||reviewing">Question {{index+1}}/{{data.items.length}} · {{data.items.length-missing}} answered</p></div><div class="row"><strong v-if="timer&&!ended" class="compact-timer" aria-label="Time remaining">{{timer}}</strong><details ref="menu" class="study-menu"><summary aria-label="Round menu">•••</summary><div><button @click="menu.open=false;navigator.open()">Questions</button><button v-if="!ended" :disabled="locked" @click="menu.open=false;requestFinish()">{{data.mode==='fresh'?(missing?'Review unanswered':'Finish catch'):'Submit round'}}</button><button @click="menu.open=false;help.open()">Study help</button></div></details></div></div>
<StudyStatus :status="finishing?'Finishing round…':status" :error="finishError||error" :pending="pending" :busy="busy||finishing" @retry="finishError?finish(remaining===0):retry()" @reload="reload"/>

<section v-if="ended&&!reviewing" class="panel completion-summary"><h2>{{data.mode==='fresh'?'Catch complete':'Round complete'}}</h2><strong class="completion-score">{{data.score}}/{{data.items.length}}</strong><p>Correct · {{Math.round(data.score/data.items.length*100)}}%</p><p role="status">Your progress is saved.</p><p v-if="data.mode==='fresh'">{{page.props.community?.habits.completed_today?'Today’s stamp is saved.':'Catch recorded.'}}</p><div class="row"><button class="primary" @click="reviewing=true;move(0)">Review answers</button><Link class="button" href="/">Back to Counter</Link></div><Link v-if="data.mode==='fresh'" class="summary-next" href="/flashcards">Continue with Memory Maki</Link></section>
<template v-else-if="q"><SlidingPanel ref="cardStage" :panel-key="index" label="Practice question" focus-on-change class="panel focused-question study-card-stage"><div class="card-meta"><span>{{q.subject}}</span><button class="plain" :disabled="locked" :aria-pressed="bookmarks.includes(q.id)" @click="router.post('/bookmarks/'+q.id,{bookmarked:!bookmarks.includes(q.id)},{preserveScroll:true})">{{bookmarks.includes(q.id)?'Bookmarked':'Bookmark'}}</button></div><h2 ref="heading" data-stage-focus tabindex="-1" class="pre question-stem">{{q.stem}}</h2><div class="options"><button v-for="(option,i) in q.options" :key="i" :disabled="locked||ended||q.checked" :aria-pressed="q.answer===String.fromCharCode(65+i)" :class="{selected:q.answer===String.fromCharCode(65+i),correct:q.key===String.fromCharCode(65+i),incorrect:q.key&&q.answer===String.fromCharCode(65+i)&&q.answer!==q.key}" @click="save(String.fromCharCode(65+i))"><strong>{{String.fromCharCode(65+i)}}.</strong><span>{{option}}</span></button></div><Feedback :key="q.item_id" :question="q"/><p v-if="ended&&!q.key" class="notice">Your administrator has not released the explanations yet.</p></SlidingPanel>
<StudyDock><div class="round-actions" :class="{'with-check':['fresh','tutor'].includes(data.mode)}"><button :disabled="index===0||locked" @click="move(index-1)">Previous</button><button class="question-count" :disabled="locked" aria-label="Open question navigator" @click="navigator.open()">{{index+1}}/{{data.items.length}}</button><button v-if="['fresh','tutor'].includes(data.mode)" :class="{primary:canCheck&&q.answer&&action.kind!=='finish'}" :disabled="locked||!q.answer||!canCheck" @click="save(q.answer,true)">{{q.checked?'Checked':'Check answer'}}</button><button :class="{primary:action.kind==='finish'||!canCheck||!q.answer}" :disabled="locked" :aria-label="action.label" @click="advance">{{finishing?'Finishing…':action.kind==='missing'?'Review '+missing:action.label}}</button></div></StudyDock></template>
<StudySheet ref="navigator" title="Questions"><div class="question-jumps"><button v-for="(item,i) in data.items" :key="item.item_id" :disabled="locked" :class="{selected:i===index,answered:item.answer}" :aria-label="'Question '+(i+1)+(item.answer?', answered':', unanswered')" @click="reviewing=ended;move(i)">{{i+1}}<span v-if="item.answer" aria-hidden="true"> ✓</span></button></div><p>{{missing}} unanswered</p></StudySheet>
<StudySheet ref="help" title="Study help"><p v-if="data.mode==='fresh'">Answer every question, then select Finish catch. Check answer shows feedback before you finish.</p><p v-else>Submit your saved answers when ready. Unanswered questions count as incorrect.</p><p v-if="data.deadline">Leaving does not pause the timer.</p><p>Keyboard: A–D or 1–4 selects an answer outside a text field. Retry any failed save before continuing.</p></StudySheet>
<StudySheet ref="submitDialog" title="Submit round" :busy="finishing"><p>{{missing?missing+' unanswered questions will count as incorrect.':'All answers are saved.'}}</p><template #actions><button :disabled="finishing" @click="submitDialog.close()">Keep reviewing</button><button class="primary" :disabled="locked" @click="finish()">{{finishing?'Finishing…':'Submit round'}}</button></template></StudySheet>
</template>
